import 'package:flutter_blue_plus/flutter_blue_plus.dart';
Future<List<ScanResult>> scan()async{
  final results=<ScanResult>[];
  final sub=FlutterBluePlus.scanResults.listen((r){for(final x in r){if(!results.any((y)=>y.device.remoteId==x.device.remoteId))results.add(x);}});
  await FlutterBluePlus.startScan(timeout:const Duration(seconds:{{scan_seconds}}));
  await Future.delayed(const Duration(seconds:{{scan_seconds}}));
  await sub.cancel();
  return results;}
